        compose.setContent { ConversationListRoute(viewModel) { peer -> opened += peer } }
    }

    private fun open(name: String) {
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_INPUT).performTextClearance()
        if (name.isNotEmpty()) compose.onNodeWithTag(HookIds.NEW_CONVERSATION_INPUT).performTextInput(name)
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_SUBMIT).performClick()
        compose.waitForIdle()
    }

    @Test
