        compose.onNodeWithTag(HookIds.CONVERSATION_LIST).assertExists()
        compose.onNodeWithText(FixedTexts.NO_CONVERSATIONS).assertExists()
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_SUBMIT).assertTextEquals(FixedTexts.OPEN)
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_ERROR).assertDoesNotExist()
    }

    @Test
    fun `CORE-SEND-001 AC-F2-1 SX-4 Open with a valid name opens the lowercase conversation and clears the field`() {
        show()
        open("Bob")
        assertEquals(listOf("bob"), opened)
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_INPUT).assertTextEquals("")
        compose.onNodeWithTag(HookIds.NEW_CONVERSATION_ERROR).assertDoesNotExist()
