    @Test
    fun `CORE-SEND-002 AC-F2-2 SX-4 an invalid recipient shows the fixed text, keeps the text and opens nothing`() {
        show()
        for (name in listOf("bob smith", "", "al!ce", "b".repeat(33))) {
            open(name)
            compose.onNodeWithTag(HookIds.NEW_CONVERSATION_ERROR).assertTextEquals(FixedTexts.INVALID_NAME)
            if (name.isNotEmpty()) compose.onNodeWithTag(HookIds.NEW_CONVERSATION_INPUT).assert(hasText(name))
        }
        assertTrue(opened.isEmpty())
